  const active=state.briefVersions?.find(v=>v.sourceId===input.briefRevision?.sourceId);if(active){const prior=await read(path.join(location(state.jobId),'input-'+active.fromRevision+'.json'));if(briefTextSHA256(input.brief)!==active.textSHA256||engineeringDigest(prior)!==input.briefRevision.priorInputSHA256)throw Error('BRIEF_REVISION_INPUT_CHANGED');if(!routingAssumptionsPreserved(prior.routingConditions,input.routingConditions))throw Error('BRIEF_ROUTING_ASSUMPTION_UPGRADE');if(prior.lightingEnvironment?.status==='assumed'&&input.lightingEnvironment?.status!=='assumed')throw Error('BRIEF_ASSUMPTION_UPGRADE');for(const section of ['lightingEnvironment','glareAssessment'])for(const room of prior[section]?.rooms||[])if(room.status==='assumed'&&input[section]?.rooms.find(r=>r.roomId===room.roomId)?.status!=='assumed')throw Error('BRIEF_ASSUMPTION_UPGRADE');}
