    const lease=await read(leaseFile);if(state.modelSHA256||state.delivery||state.status!=='quality_assessing'||lease.action!=='solve_lighting'||state.history.at(-1)?.event!=='initial_lighting_search_started')throw Error('LIGHTING_RECOVERY_NOT_APPLICABLE');if(ownerLive(lease.pid))throw Error('ENGINEERING_BUSY: calculation owner is alive or cannot be verified');if(state.lightingOptimization?.publicationStarted||await maybeStat(path.join(dir,'model-'+state.revision+'.json')))throw Error('LIGHTING_PUBLICATION_UNCONFIRMED: initial publication needs journal reconciliation; no CAD replay');
    const archive=path.join(dir,'initial-lighting-interrupted-'+q.requestId+'.json');try{await fs.copyFile(leaseFile,archive,fs.constants.COPYFILE_EXCL);}catch(error){if(error.code!=='EEXIST'||await hashFile(archive)!==await hashFile(leaseFile))throw error;}if(ownerLive(lease.pid)||await hashFile(archive)!==await hashFile(leaseFile))throw Error('LIGHTING_RECOVERY_OWNER_CHANGED');
